function validate([pressedKeys]) {
  if (typeof pressedKeys !== 'string' || pressedKeys.length < 1 || pressedKeys.length > 100000) return 'pressedKeys needs 1 to 10^5 characters.';
  if (!/^[2-9]+$/.test(pressedKeys)) return "pressedKeys may only contain the digits '2' to '9'.";
  return null;
}

