function countTexts(pressedKeys) {
  const MOD = 1_000_000_007;
  const n = pressedKeys.length;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;

  for (let i = 1; i <= n; i++) {
    const key = pressedKeys[i - 1];
    const maxPresses = key === '7' || key === '9' ? 4 : 3;
    for (let presses = 1; presses <= maxPresses && presses <= i; presses++) {
      if (pressedKeys[i - presses] !== key) break;
      dp[i] = (dp[i] + dp[i - presses]) % MOD;
    }
  }

  return dp[n];
}

