function countTexts(pressedKeys) {
  // Letters never span two different digits, so each run of one digit is independent.
  // A run of length L on a key with k letters is a composition of L into parts 1..k; count those exactly with BigInt.
  const letters = { 2: 'abc', 3: 'def', 4: 'ghi', 5: 'jkl', 6: 'mno', 7: 'pqrs', 8: 'tuv', 9: 'wxyz' };
  let total = 1n;
  let start = 0;
  while (start < pressedKeys.length) {
    let end = start;
    while (end < pressedKeys.length && pressedKeys[end] === pressedKeys[start]) end++;
    const length = end - start;
    const parts = letters[pressedKeys[start]].length;
    const ways = [1n];
    for (let j = 1; j <= length; j++) {
      let sum = 0n;
      for (let p = 1; p <= parts && p <= j; p++) sum += ways[j - p];
      ways.push(sum);
    }
    total *= ways[length];
    start = end;
  }
  return Number(total % 1000000007n);
}

