function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const digits = '23456789';
  if (size === 'large') {
    const n = 10000;
    const mode = pick(3);
    if (mode === 0) return ['79'[pick(2)].repeat(n)];
    let keys = '';
    while (keys.length < n) {
      const run = mode === 1 ? 1 + pick(8) : 1 + pick(60);
      keys += digits[pick(8)].repeat(run);
    }
    return [keys.slice(0, n)];
  }
  const pool = Array.from({ length: 1 + pick(3) }, () => digits[pick(8)]);
  const n = 1 + pick(12);
  let keys = '';
  while (keys.length < n) keys += pool[pick(pool.length)].repeat(1 + pick(5));
  return [keys.slice(0, n)];
}
